#!/usr/bin/env python3
"""Standalone stdlib-only driver. Runs exclusively inside one Slurm allocation."""
import argparse
from datetime import datetime, timezone
import hashlib
import json
import math
import os
from pathlib import Path
import re
import shutil
import signal
import subprocess
import time

THRESHOLDS={'Energy change':2e-7,'RMS gradient':8e-6,'MAX gradient':3e-5,
            'RMS step':1e-4,'MAX step':2e-4}
NUMBER=r'[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[EeDd][+-]?\d+)?'
ROW=re.compile(r'^\s*(Energy change|RMS gradient|MAX gradient|RMS step|MAX step)\s+'
               r'('+NUMBER+r')\s+('+NUMBER+r')\s+(YES|NO)\s*$')

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def write_json(path,data):
    path.write_text(json.dumps(data,indent=2,sort_keys=True)+'\n',encoding='utf-8')

def normal_and_identity(text):
    if 'ORCA TERMINATED NORMALLY' not in text:
        raise ValueError('normal termination missing')
    if re.search(r'ORCA\s+(?:finished by error|ERROR)|ERROR\s*!!!',text,re.I):
        raise ValueError('ORCA error present')
    # LiM_2plus adaptation (exp_line_20261031): charge +2 / doublet / 49 electrons.
    for pattern,want in [(r'Total Charge\s+Charge\s+\.{3,}\s+(-?\d+)',2),
                         (r'Multiplicity\s+Mult\s+\.{3,}\s+(\d+)',2),
                         (r'Number of Electrons\s+NEL\s+\.{3,}\s+(\d+)',49)]:
        values=re.findall(pattern,text)
        if not values or any(int(v)!=want for v in values):
            raise ValueError('runtime electronic identity missing or wrong')

def validate_opt(text):
    normal_and_identity(text)
    strict=re.findall(r'Strict Convergence\s+\.{3,}\s+(True|False)',text)
    if not strict or any(v!='True' for v in strict):
        raise ValueError('strict convergence echo must be True throughout')
    if 'THE OPTIMIZATION HAS CONVERGED' not in text:
        raise ValueError('optimizer convergence marker missing')
    positions=[i for i,line in enumerate(text.splitlines()) if 'Geometry convergence' in line]
    if not positions: raise ValueError('missing geometry convergence table')
    lines=text.splitlines(); rows={}
    for line in lines[positions[-1]+1:positions[-1]+18]:
        match=ROW.fullmatch(line)
        if not match: continue
        name=match[1]
        if name in rows: raise ValueError('duplicate convergence row')
        value=float(match[2].replace('D','E').replace('d','e'))
        tol=float(match[3].replace('D','E').replace('d','e'))
        frozen=THRESHOLDS[name]
        passed=(math.isfinite(value) and math.isfinite(tol)
                and abs(tol-frozen)<=5e-12 and abs(value)<=frozen and match[4]=='YES')
        rows[name]={'value':value,'tolerance':tol,'frozen':frozen,'passed':passed}
    if set(rows)!=set(THRESHOLDS) or not all(r['passed'] for r in rows.values()):
        raise ValueError('frozen five criteria not satisfied: '+json.dumps(rows,sort_keys=True))
    return rows

def read_xyz(path):
    lines=path.read_text().splitlines(); n=int(lines[0]); rows=[s.split() for s in lines[2:2+n]]
    if len(rows)!=n or any(len(r)!=4 for r in rows): raise ValueError('invalid XYZ')
    symbols=[r[0] for r in rows]; coords=[[float(v) for v in r[1:]] for r in rows]
    if not all(math.isfinite(v) for r in coords for v in r): raise ValueError('nonfinite XYZ')
    return symbols,coords

def bond_graph(symbols,coords):
    # LiM_2plus adaptation: Li must be a known element, or every leg dies on
    # 'unexpected element' before any QC runs.
    radii={'C':.76,'H':.31,'O':.66,'Li':1.28}
    if any(s not in radii for s in symbols): raise ValueError('unexpected element')
    return {(i,j) for i in range(len(symbols)) for j in range(i+1,len(symbols))
            if sum((a-b)**2 for a,b in zip(coords[i],coords[j]))**.5
            <=1.3*(radii[symbols[i]]+radii[symbols[j]])}

def covalent_graph(symbols,coords):
    return {e for e in bond_graph(symbols,coords) if all(symbols[i]!='Li' for i in e)}

def run_orca(stage,orca,timeout):
    stem='job_opt' if stage.name=='opt' else 'job_freq'
    with (stage/(stem+'.log')).open('w') as stdout, (stage/(stem+'.stderr')).open('w') as stderr:
        proc=subprocess.Popen([orca,stem+'.inp'],cwd=str(stage),stdout=stdout,stderr=stderr,
                              start_new_session=True)
        try:
            code=proc.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            os.killpg(proc.pid,signal.SIGTERM)
            try: proc.wait(timeout=10)
            except subprocess.TimeoutExpired:
                os.killpg(proc.pid,signal.SIGKILL); proc.wait()
            raise TimeoutError('shared allocation time budget exhausted')
        if code: raise RuntimeError('ORCA return code '+str(code))

def execute(attempt,orca,limit_seconds=5340,runner=run_orca):
    attempt=Path(attempt).resolve(); deadline=time.monotonic()+limit_seconds
    result={'status':'starting','started_utc':datetime.now(timezone.utc).isoformat(),
            'time_budget_seconds':limit_seconds,'stages':{}}
    def remain():
        value=deadline-time.monotonic()
        if value<=0: raise TimeoutError('shared wallclock exhausted')
        return value
    try:
        opt=attempt/'opt'; opt.mkdir()
        for name in ['geom.xyz','job_opt.inp']: shutil.copy2(attempt/name,opt/name)
        runner(opt,orca,remain())
        text=(opt/'job_opt.log').read_text(errors='replace')
        try: criteria=validate_opt(text)
        except ValueError as exc:
            result.update(status='opt_qc_failed',reason=str(exc)); return result
        syms,start=read_xyz(attempt/'geom.xyz'); final_syms,final=read_xyz(opt/'job_opt.xyz')
        if syms!=final_syms or covalent_graph(syms,start)!=covalent_graph(final_syms,final):
            raise ValueError('optimized species/atom order/connectivity changed')
        final_sha=sha(opt/'job_opt.xyz')
        result['stages']['opt']={'criteria':criteria,'input_sha256':sha(opt/'job_opt.inp'),
            'log_sha256':sha(opt/'job_opt.log'),'final_geometry_sha256':final_sha}
        write_json(attempt/'opt_qc.json',result['stages']['opt'])
        # Allocate no new wallclock: frequency consumes only remaining time.
        freq=attempt/'freq'; freq.mkdir()
        shutil.copy2(opt/'job_opt.xyz',freq/'geom.xyz')
        shutil.copy2(attempt/'job_freq.inp',freq/'job_freq.inp')
        if sha(freq/'geom.xyz')!=final_sha: raise ValueError('frequency geometry linkage failed')
        runner(freq,orca,remain())
        ftext=(freq/'job_freq.log').read_text(errors='replace'); normal_and_identity(ftext)
        if sha(freq/'geom.xyz')!=final_sha: raise ValueError('frequency input geometry mutated')
        modes=re.findall(r'^\s*(\d+):\s*('+NUMBER+r')\s+cm\*\*-1',ftext,re.M)
        if len(modes)!=3*len(syms) or [int(i) for i,v in modes]!=list(range(3*len(syms))):
            raise ValueError('frequency count incomplete')
        negative=[float(v.replace('D','E')) for i,v in modes if float(v.replace('D','E'))<0]
        if not (freq/'job_freq.hess').is_file(): raise ValueError('fresh Hessian missing')
        result['stages']['freq']={'input_sha256':sha(freq/'job_freq.inp'),
            'geometry_sha256':final_sha,'log_sha256':sha(freq/'job_freq.log'),
            'hess_sha256':sha(freq/'job_freq.hess'),'imaginary_frequencies_cm1':negative}
        result['status']='frequency_qc_failed' if negative else 'technical_complete_scientific_qc_pending'
    except (OSError,ValueError,RuntimeError,TimeoutError) as exc:
        result.update(status='execution_or_identity_failed',reason=str(exc))
    finally:
        result['finished_utc']=datetime.now(timezone.utc).isoformat()
        write_json(attempt/'workflow_result.json',result)
    return result

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--attempt',type=Path,required=True)
    ap.add_argument('--orca',required=True); args=ap.parse_args()
    if not os.environ.get('SLURM_JOB_ID'): raise SystemExit('must run inside Slurm')
    result=execute(args.attempt,args.orca)
    print(json.dumps(result,indent=2))
    return 0 if result['status']=='technical_complete_scientific_qc_pending' else 2

if __name__=='__main__': raise SystemExit(main())

